//! Type coercion for binary expressions generated by compiler passes.

use super::{CircuitEditor, Error, Field, InnerKind, NodeId, Ty, TypeId};

impl Ty {
    pub(super) fn date(self) -> bool {
        matches!(
            self,
            Self::Date | Self::Time | Self::Timestamp | Self::TimestampTz
        )
    }

    pub(super) fn interval(self) -> bool {
        matches!(self, Self::LongInterval | Self::ShortInterval)
    }

    pub(super) fn numeric(self) -> bool {
        matches!(
            self,
            Self::Integer | Self::Decimal | Self::Double | Self::Real
        )
    }
}

impl CircuitEditor {
    /// The erased waterline output of a keyed input has type TypedBox<T, DynData>.
    pub fn dynamic_box_type(&mut self, output: TypeId) -> Result<TypeId, Error> {
        self.box_data_type(output, "DynData", Vec::new())
    }

    /// A rolling trace reads its ordering key through TypedBox<T, DynDataTyped<T>>.
    pub fn typed_box_type(&mut self, output: TypeId) -> Result<TypeId, Error> {
        self.box_data_type(
            output,
            "DynDataTyped",
            vec![Field::Reference(output.into())],
        )
    }

    fn box_data_type(
        &mut self,
        output: TypeId,
        name: &str,
        args: Vec<Field>,
    ) -> Result<TypeId, Error> {
        let dynamic = self.inner_at(
            output.into(),
            InnerKind::Type(Ty::User),
            [
                ("name", Field::Data(name.into())),
                ("typeArgs", Field::Array(args)),
                ("code", Field::Data("USER".into())),
                ("mayBeNull", Field::Data(false.into())),
            ],
        )?;
        let boxed = self.inner_at(
            output.into(),
            InnerKind::Type(Ty::TypedBox),
            [
                ("name", Field::Data("TypedBox".into())),
                (
                    "typeArgs",
                    Field::Array(vec![
                        Field::Reference(output.into()),
                        Field::Reference(dynamic),
                    ]),
                ),
                ("code", Field::Data("TYPEDBOX".into())),
                ("mayBeNull", Field::Data(false.into())),
            ],
        )?;
        self.type_id(boxed)
    }

    pub fn variant_type(&mut self, sample: NodeId, nullable: bool) -> Result<TypeId, Error> {
        self.primitive_singleton(sample, Ty::Variant, "VARIANT", nullable)
    }

    pub fn uuid_type(&mut self, sample: NodeId, nullable: bool) -> Result<TypeId, Error> {
        self.primitive_singleton(sample, Ty::Uuid, "UUID", nullable)
    }

    /// The floating-point literal constructors use one canonical type per nullability.
    pub fn float_literal_type(&mut self, sample: TypeId, nullable: bool) -> Result<TypeId, Error> {
        let kind = self.type_kind(sample)?;
        let code = match kind {
            Ty::Real => "REAL",
            Ty::Double => "DOUBLE",
            _ => return Err(Error::new("expected a floating-point literal type")),
        };
        self.primitive_singleton(sample.into(), kind, code, nullable)
    }

    pub fn bool_type(&mut self, sample: NodeId, nullable: bool) -> Result<TypeId, Error> {
        self.primitive_singleton(sample, Ty::Bool, "BOOL", nullable)
    }

    /// Return SQL field names in declaration order, retaining quoted identifier spelling.
    pub fn original_field_names(&self, tuple: TypeId) -> Result<Option<Vec<String>>, Error> {
        let Some(record) = self
            .node(tuple.into())?
            .field("originalStruct")
            .and_then(Field::node_id)
        else {
            return Ok(None);
        };
        self.node(record)?
            .edges("fields")?
            .into_iter()
            .map(|field| Ok(self.node(field)?.sql_identifier_name()?.to_owned()))
            .collect::<Result<Vec<_>, _>>()
            .map(Some)
    }

    pub(super) fn number(&self, ty: TypeId, name: &str) -> Result<i64, Error> {
        self.node(ty.0)?
            .data(name)
            .and_then(|v| v.as_i64())
            .ok_or_else(|| Error::new(format!("type requires integer {name}")))
    }

    /// Allocate an integer type at the source location of another type.
    pub fn integer_type(
        &mut self,
        origin: TypeId,
        width: i64,
        signed: bool,
        nullable: bool,
    ) -> Result<TypeId, Error> {
        if !matches!(width, 8 | 16 | 32 | 64 | 128) {
            return Err(Error::new("unsupported integer width"));
        }
        let code = format!("{}{width}", if signed { "INT" } else { "UINT" });
        self.inner_at(
            origin.0,
            InnerKind::Type(Ty::Integer),
            [
                ("width", Field::Data(width.into())),
                ("signed", Field::Data(signed.into())),
                ("code", Field::Data(code.into())),
                ("mayBeNull", Field::Data(nullable.into())),
            ],
        )
        .map(TypeId)
    }

    pub(super) fn decimal_type(
        &mut self,
        origin: TypeId,
        precision: i64,
        scale: i64,
        nullable: bool,
    ) -> Result<TypeId, Error> {
        if !(1..=38).contains(&precision) || !(0..=precision).contains(&scale) {
            return Err(Error::new(format!(
                "unsupported DECIMAL({precision},{scale})"
            )));
        }
        self.inner_at(
            origin.0,
            InnerKind::Type(Ty::Decimal),
            [
                ("precision", Field::Data(precision.into())),
                ("scale", Field::Data(scale.into())),
                ("code", Field::Data("DECIMAL".into())),
                ("mayBeNull", Field::Data(nullable.into())),
            ],
        )
        .map(TypeId)
    }

    pub(super) fn primitive(
        &mut self,
        origin: TypeId,
        kind: Ty,
        code: &str,
        nullable: bool,
    ) -> Result<TypeId, Error> {
        self.inner_at(
            origin.0,
            InnerKind::Type(kind),
            [
                ("code", Field::Data(code.into())),
                ("mayBeNull", Field::Data(nullable.into())),
            ],
        )
        .map(TypeId)
    }

    pub(super) fn common_type(
        &mut self,
        left: TypeId,
        right: TypeId,
        strings: bool,
    ) -> Result<TypeId, Error> {
        let a = self.type_kind(left)?;
        let b = self.type_kind(right)?;
        if a == Ty::Null {
            return self.with_nullability(right, true);
        }
        if b == Ty::Null {
            return self.with_nullability(left, true);
        }
        let nullable = self.nullable(left)? || self.nullable(right)?;
        if self.same_type_ignoring_nullability(left, right)?
            || matches!(a, Ty::Timestamp | Ty::TimestampTz) && b.date()
        {
            return self.with_nullability(left, nullable);
        }
        if matches!(b, Ty::Timestamp | Ty::TimestampTz) && a.date() {
            return self.with_nullability(right, nullable);
        }

        if a == b && matches!(a, Ty::Tuple | Ty::RawTuple | Ty::Array | Ty::Map) {
            let tuple = matches!(a, Ty::Tuple | Ty::RawTuple);
            let slot = if tuple { "tupFields" } else { "typeArgs" };
            let left_args = self.node(left.0)?.edges(slot)?;
            let right_args = self.node(right.0)?.edges(slot)?;
            if left_args.len() != right_args.len() {
                return Err(Error::new("common type needs matching arity"));
            }
            let mut args = Vec::with_capacity(left_args.len());
            for (a, b) in left_args.into_iter().zip(right_args) {
                args.push(Field::Reference(
                    self.common_type(self.type_id(a)?, self.type_id(b)?, strings || !tuple)?
                        .0,
                ));
            }
            let code = self
                .node(left.0)?
                .data("code")
                .cloned()
                .ok_or_else(|| Error::new("missing type code"))?;
            let mut fields = vec![
                (slot, Field::Array(args)),
                ("code", Field::Data(code)),
                (
                    "mayBeNull",
                    Field::Data(
                        (if tuple {
                            a == Ty::Tuple && self.nullable(left)?
                        } else {
                            nullable
                        })
                        .into(),
                    ),
                ),
            ];
            if let Some(name) = self.node(left.0)?.data("name") {
                fields.push(("name", Field::Data(name.clone())));
            }
            return self.empty_type(left, a, fields);
        }
        if strings && (a == Ty::String || b == Ty::String) && a != b {
            let other = if a == Ty::String { right } else { left };
            let kind = self.type_kind(other)?;
            if kind == Ty::Decimal {
                return self.decimal_type(other, 38, 19, nullable);
            }
            if kind.numeric() || kind.date() || kind.interval() || kind == Ty::Bool {
                return self.with_nullability(other, nullable);
            }
        }
        if strings && a == b && matches!(a, Ty::String | Ty::Binary) {
            let lp = self.number(left, "precision")?;
            let rp = self.number(right, "precision")?;
            let precision = if lp < 0 || rp < 0 { -1 } else { lp.max(rp) };
            let fixed = [left, right].into_iter().all(|ty| {
                self.node(ty.0)
                    .ok()
                    .and_then(|n| n.data("fixed"))
                    .and_then(|v| v.as_bool())
                    == Some(true)
            });
            return self
                .derive_inner(
                    left.0,
                    [
                        ("fixed", Field::Data(fixed.into())),
                        ("precision", Field::Data(precision.into())),
                        ("mayBeNull", Field::Data(nullable.into())),
                    ],
                )
                .map(TypeId);
        }
        match (a, b) {
            (Ty::Integer, Ty::Integer) => {
                let width = self
                    .number(left, "width")?
                    .max(self.number(right, "width")?);
                let mut signed = true;
                for ty in [left, right] {
                    if self.number(ty, "width")? == width {
                        signed &= self
                            .node(ty.0)?
                            .data("signed")
                            .and_then(|v| v.as_bool())
                            .ok_or_else(|| Error::new("missing integer signedness"))?;
                    }
                }
                self.integer_type(left, width, signed, nullable)
            }
            (Ty::Integer | Ty::Real, Ty::Double | Ty::Real) => {
                self.with_nullability(right, nullable)
            }
            (Ty::Double | Ty::Real, Ty::Integer | Ty::Real | Ty::Double) => {
                self.with_nullability(left, nullable)
            }
            (Ty::Decimal, Ty::Real | Ty::Double) => {
                self.primitive(right, Ty::Double, "DOUBLE", nullable)
            }
            (Ty::Real | Ty::Double, Ty::Decimal) => {
                self.primitive(left, Ty::Double, "DOUBLE", nullable)
            }
            (Ty::Decimal, Ty::Integer) | (Ty::Integer, Ty::Decimal) => {
                let (decimal, int) = if a == Ty::Decimal {
                    (left, right)
                } else {
                    (right, left)
                };
                let digits = match self.number(int, "width")? {
                    8 => 3,
                    16 => 5,
                    32 => 10,
                    64 => 19,
                    128 => 38,
                    _ => return Err(Error::new("unsupported integer precision")),
                };
                self.decimal_type(
                    right,
                    self.number(decimal, "precision")?.max(digits),
                    self.number(decimal, "scale")?,
                    nullable,
                )
            }
            (Ty::Decimal, Ty::Decimal) => {
                let ls = self.number(left, "scale")?;
                let rs = self.number(right, "scale")?;
                let scale = ls.max(rs);
                let precision = scale
                    + (self.number(left, "precision")? - ls)
                        .max(self.number(right, "precision")? - rs);
                if precision >= 38 {
                    return Err(Error::new("DECIMAL common type needs an explicit cast"));
                }
                self.decimal_type(left, precision, scale, nullable)
            }
            _ => Err(Error::new(format!(
                "no implicit conversion between {a:?} and {b:?}"
            ))),
        }
    }

    fn empty_type(
        &mut self,
        sample: TypeId,
        kind: Ty,
        mut fields: Vec<(&str, Field)>,
    ) -> Result<TypeId, Error> {
        if self.node(sample.0)?.field("sourceEmpty").is_some() {
            fields.push(("sourceEmpty", Field::Data(true.into())));
        }
        self.inner_with_fields(InnerKind::Type(kind), fields)
            .map(TypeId)
    }
}

impl crate::Node {
    /// Spelling of the SQL identifier carried by a struct or one of its fields.
    pub fn sql_identifier_name(&self) -> Result<&str, Error> {
        let Some(Field::Object(name)) = self.field("name") else {
            return Err(Error::new("missing SQL identifier"));
        };
        let Some(Field::Data(name)) = name.get("name") else {
            return Err(Error::new("missing SQL identifier spelling"));
        };
        name.as_str()
            .ok_or_else(|| Error::new("SQL identifier must be a string"))
    }
}
